catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    g_form.hideFieldMsg('pickup_datetime', true);

    var dateValue = newValue || g_form.getValue('pickup_datetime');
    if (!dateValue) {
        return;
    }

    var formattedDate = String(dateValue).replace(' ', 'T');
    var selectedDateTime = new Date(formattedDate);
    var now = new Date();

    if (isNaN(selectedDateTime.getTime())) {
        g_form.setValue('pickup_datetime', '');
        g_form.showFieldMsg('pickup_datetime', 'Please enter a valid date and time.', 'error');
        return;
    }

    if (selectedDateTime <= now) {
        g_form.setValue('pickup_datetime', '');
        g_form.showFieldMsg('pickup_datetime', 'The preferred date and time must be in the future.', 'error');
        return;
    }
}
